import{_ as t,C as s,o as n,c as o,j as i,E as l,a as e,a2 as d}from"./chunks/framework.C21TwvGF.js";const k=JSON.parse(`{"title":"4-hafta","description":"","frontmatter":{"title":"4-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf (UX/UI)","link":"/9-sinf/"},"n":4,"bob":"I-bob · UX/UI dizayn nazariyasi va asoslari","lessons":[{"g":10,"title":"Shrift (tipografiya) va uning UX dizaynga ta'siri","lead":"Chiroyli rasm va tugmalar bo'lsa-yu, matnni o'qib bo'lmasa, ilovadan kim foydalanadi? Ushbu darsda interfeysning \\"ovoz ohangi\\" hisoblangan tipografiya, shrift turlari va ularni Figma'da sozlashni o'rganamiz.","link":"/9-sinf/hafta-04/dars-1","slide":"/slaydlar/9-sinf/hafta-04/dars-1.html","test":"/slaydlar/9-sinf/hafta-04/dars-1-test.html"},{"g":11,"title":"UI elementlarida rang nazariyasi","lead":"Nega ayrim ilovalar ko'zni quvontiradi, boshqalari esa 5 soniyada charchatadi? Ushbu darsda ranglar g'ildiragi, 4 xil rang palitrasi, 60-30-10 qoidasi va WCAG kontrast talablarini o'rganamiz.","link":"/9-sinf/hafta-04/dars-2","slide":"/slaydlar/9-sinf/hafta-04/dars-2.html","test":"/slaydlar/9-sinf/hafta-04/dars-2-test.html"},{"g":12,"title":"UI kompozitsiyasi va vizual ierarxiya asoslari","lead":"Shriftlar va ranglar chiroyli tanlangan, lekin interfeysda nima qayerdaligi tushunarsizmi? Ushbu darsda kompozitsiyaning 4 oltin tamoyili, vizual ierarxiya va bo'sh joy (White space) qudratini o'rganamiz.","link":"/9-sinf/hafta-04/dars-3","slide":"/slaydlar/9-sinf/hafta-04/dars-3.html","test":"/slaydlar/9-sinf/hafta-04/dars-3-test.html"}],"test":"/slaydlar/9-sinf/hafta-04/hafta-test.html"}},"headers":[],"relativePath":"9-sinf/hafta-04/index.md","filePath":"9-sinf/hafta-04/index.md"}`),h={name:"9-sinf/hafta-04/index.md"},g={class:"blk"},u={id:"uyga-vazifa",tabindex:"-1"};function f(m,a,c,y,p,b){const r=s("Icon");return n(),o("div",null,[i("div",g,[i("h2",u,[l(r,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–30 daqiqa. Natijalarni Figma dasturidagi alohida faylda saqlang. Topshirish: keyingi dars boshida mentorga Figma havolasini ko&#39;rsating.</p><h3 id="_10-dars-uchun-shrift-va-tipografiya" tabindex="-1">10-dars uchun (Shrift va tipografiya) <a class="header-anchor" href="#_10-dars-uchun-shrift-va-tipografiya" aria-label="Permalink to &quot;10-dars uchun (Shrift va tipografiya)&quot;">​</a></h3><p><strong>1-topshiriq: «Tipografik ierarxiya va shrift juftligi»</strong></p><ol><li>Figma&#39;da <code>Mobile (375x812)</code> o&#39;lchamli Frame oching.</li><li>Google Fonts&#39;dan ikkita shrift juftligini tanlang (masalan: Sarlavhalar uchun <em>Poppins</em>, asosiy matn uchun <em>Inter</em>).</li><li>Yangiliklar kartasi dizaynini yarating: <ul><li>Kategoriya tegi: <code>10px BOLD</code>, bosh harflarda;</li><li>Asosiy sarlavha: <code>20px SemiBold</code>, Line Height: <code>130%</code>;</li><li>Qisqa tavsif: <code>14px Regular</code>, Line Height: <code>150%</code>;</li><li>Sana va muallif: <code>12px Muted (och kulrang)</code>.</li></ul></li></ol><p><strong>Kutiladigan natija:</strong> o&#39;qilishi oson, tipografik ierarxiyasi to&#39;g&#39;ri qurilgan yangilik kartasi.</p><hr><h3 id="_11-dars-uchun-ui-elementlarida-rang-nazariyasi" tabindex="-1">11-dars uchun (UI elementlarida rang nazariyasi) <a class="header-anchor" href="#_11-dars-uchun-ui-elementlarida-rang-nazariyasi" aria-label="Permalink to &quot;11-dars uchun (UI elementlarida rang nazariyasi)&quot;">​</a></h3><p><strong>2-topshiriq: «60-30-10 rang palitrasi va kontrast»</strong></p><ol><li>Figma&#39;da o&#39;zingiz tanlagan brend yo&#39;nalishi (masalan: ekologik mahsulotlar yoki musiqa ilovasi) uchun 3 ta rang tanlang (60% fon, 30% karta foni, 10% yorqin brend CTA tugmasi).</li><li>Shu ranglar asosida bitta «Mahsulot kartasi» (Product Card) chizing: Rasm, Mahsulot nomi, Narxi, Chegirma belgisi va «Sotib olish» tugmasi.</li><li>WebAIM Contrast Checker orqali tugma foni va matni orasidagi kontrast kamida <code>4.5:1</code> ekanligini tekshiring.</li></ol><p><strong>Kutiladigan natija:</strong> 60-30-10 qoidasiga mos, WCAG kontrast talablariga javob beruvchi chiroyli karta.</p><hr><h3 id="_12-dars-uchun-ui-kompozitsiyasi-va-vizual-ierarxiya" tabindex="-1">12-dars uchun (UI kompozitsiyasi va vizual ierarxiya) <a class="header-anchor" href="#_12-dars-uchun-ui-kompozitsiyasi-va-vizual-ierarxiya" aria-label="Permalink to &quot;12-dars uchun (UI kompozitsiyasi va vizual ierarxiya)&quot;">​</a></h3><p><strong>3-topshiriq: «E-kutubxona to&#39;liq bosh ekrani»</strong></p><ol><li>Hafta davomida o&#39;rganilgan barcha bilimlarni (Tipografiya, Rang, Kompozitsiya) birlashtiring.</li><li>«E-kutubxona» mobil ilovasi bosh sahifasini 8-point grid qoidasi bo&#39;yicha chizing: <ul><li>Yuqori panel: Profil avatari, qidiruv satri;</li><li>Kompozitsion markaz: Katta «Hafta tavsiyasi» banneri va yorqin «O&#39;qishni boshlash» tugmasi;</li><li>Ritm: Gorizontal aylanuvchi «Ommabop kitoblar» kartalari qatori (bir xil 16px oraliq bilan);</li><li>Pastki navigatsiya: 4 ta asosiy bo&#39;lim ikonkalari.</li></ul></li></ol><p><strong>Kutiladigan natija:</strong> professional, muvozanatli va I-bob talablariga to&#39;liq javob beruvchi mobil bosh sahifa UI maketi.</p><hr>',16))])])}const z=t(h,[["render",f]]);export{k as __pageData,z as default};
